/** پرامپت نسخه‌دار تولید کپشن فارسی — نسخه همراه کد نگه‌داری می‌شود
 *  و هر تغییر باید نسخه را بالا ببرد تا ارزیابی (eval) بازاجرا شود. */
export const PROMPT_VERSION = 'caption-fa-v1';
const TONE_FA = {
    friendly: 'صمیمی و فروش‌محور؛ مخاطب را با «شما» خطاب کن.',
    formal: 'رسمی و مینیمال؛ جمله‌های کوتاه و بدون احساساتی‌نویسی.',
    story: 'روایتی و داستانی؛ با یک صحنه یا تجربه کوچک شروع کن.',
};
const LENGTH_FA = {
    short: 'کوتاه — حداکثر ۳ جمله.',
    medium: 'متوسط — ۴ تا ۶ جمله.',
    long: 'بلند — ۷ تا ۹ جمله، بدون گذر از ۲۲۰۰ نویسه.',
};
const GOAL_FA = {
    awareness: 'هدف کمپین: معرفی محصول و آگاهی‌سازی؛ دعوت ملایم به دایرکت.',
    sale: 'هدف کمپین: تبدیل و فروش؛ دعوت مشخص به سفارش از دایرکت.',
    engagement: 'هدف کمپین: تعامل؛ با یک پرسش ساده مخاطب را به کامنت دعوت کن.',
};
/** فقط واقعیت‌های اثبات‌شده در پرامپت می‌روند؛ فیلد غایب اصلاً ذکر نمی‌شود. */
function factsBlock(f) {
    const facts = { name: f.name };
    if (f.description.length > 0)
        facts.description = f.description;
    if (f.priceToman !== null)
        facts.priceToman = f.priceToman;
    if (f.stock !== null)
        facts.stock = f.stock;
    if (f.sku.length > 0)
        facts.sku = f.sku;
    return JSON.stringify(facts, null, 1);
}
const SYSTEM = [
    'تو دستیار تولید کپشن فارسی اینستاگرام برای یک فروشگاه تک‌فروشگاهی هستی.',
    '',
    'قواعد غیرقابل نقض:',
    '1. تنها منبع حقیقت، بلوک «واقعیت‌های محصول» است. هیچ قیمت، موجودی، تخفیف، ویژگی، اندازه، جنس یا گارانتی که در واقعیت‌ها نیست، به هیچ شکلی بساز یا حدس نزن.',
    '2. اگر فیلدی (مثلاً قیمت یا موجودی) در واقعیت‌ها نیست، درباره آن هیچ ادعایی ننویس — نه عدد، نه «موجود است»، نه «تخفیف».',
    '3. نظر مشتری، نقل‌قول، آمار فروش یا ادعای عملکردی (پرفروش‌ترین، رکورد و…) جعل نکن.',
    '4. کپشن کاملاً فارسی و روان بنویس: نیم‌فاصله درست، گیومه فارسی «»، علائم فارسی — واژه‌های لاتین فقط برای برند یا کد محصول مجاز است.',
    '5. حداکثر ۳ هشتگ مرتبط در انتهای کپشن.',
    '6. خروجی فقط و فقط یک JSON معتبر است — بدون متن اضافه و بدون بلوک کد — با این شکل:',
    '{"options":[{"caption":"...","factsUsed":["..."],"suggestions":["..."]}]}',
    'که ۱ تا ۳ گزینه دارد. factsUsed فهرست واقعیت‌های به‌کاررفته از بلوک واقعیت‌ها و suggestions پیشنهادهای اختیاری برای بهبود (بدون ادعای واقعیت جدید) است.',
].join('\n');
export function buildMessages(req) {
    const user = [
        'واقعیت‌های محصول:',
        factsBlock(req.product),
        '',
        'سبک: ' + TONE_FA[req.tone],
        'طول: ' + LENGTH_FA[req.length],
        GOAL_FA[req.goal],
        '',
        'سه گزینه کپشن متمایز بساز و فقط JSON خروجی بده.',
    ].join('\n');
    return [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: user },
    ];
}
